(()=>{const STORAGE_KEYS=['phoenixBookings','phoenixAdminTours','phoenixSettings'];const overview=document.querySelector('#overview');if(!overview||document.querySelector('#backupRestorePanel'))return;const style=document.createElement('style');style.textContent=`.backup-restore-panel{margin-top:14px;padding:18px 19px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(135deg,#fff,#f5faf8);box-shadow:var(--shadow);display:grid;grid-template-columns:1fr auto;gap:18px;align-items:center}.backup-restore-panel h2{font-size:15px;margin:4px 0 5px}.backup-restore-panel p{font-size:9px;line-height:1.55;color:#7c8e93;margin:0}.backup-kicker{font-size:7px;letter-spacing:1.2px;color:#158d89;font-weight:900}.backup-meta{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.backup-meta span{padding:6px 8px;border-radius:999px;background:#e8f4f1;color:#527078;font-size:7px;font-weight:800}.backup-actions{display:flex;gap:8px}.backup-actions button{min-width:118px}.backup-actions .restore-btn{background:#fff;color:#0c6769}.backup-status{grid-column:1/-1;display:none;padding:9px 11px;border-radius:10px;font-size:8px;font-weight:800}.backup-status.show{display:block}.backup-status.ok{background:#e0f5ef;color:#156e60}.backup-status.err{background:#fff0f0;color:#a74848}@media(max-width:760px){.backup-restore-panel{grid-template-columns:1fr}.backup-actions{width:100%}.backup-actions button{flex:1;min-width:0}}`;document.head.appendChild(style);const panel=document.createElement('section');panel.id='backupRestorePanel';panel.className='backup-restore-panel';panel.innerHTML=`<div><span class="backup-kicker">DATA SAFETY</span><h2>Backup & Restore</h2><p>Download a complete JSON backup of bookings, tour edits and business settings. Restore it later on this browser or another device.</p><div class="backup-meta"><span id="backupBookingsCount">0 bookings</span><span id="backupToursCount">0 tours</span><span id="backupLastTime">No backup created yet</span></div></div><div class="backup-actions"><button class="primary" id="createBackupBtn">↓ Create Backup</button><button class="restore-btn" id="restoreBackupBtn">↥ Restore Backup</button><input id="restoreBackupFile" type="file" accept="application/json,.json" hidden></div><div id="backupStatus" class="backup-status"></div>`;const grid=overview.querySelector('.dashboard-grid');if(grid)grid.before(panel);else overview.appendChild(panel);const $id=id=>document.getElementById(id);function readArray(key){try{const v=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(v)?v:[]}catch{return[]}}function updateMeta(){const bookings=readArray('phoenixBookings'),tours=readArray('phoenixAdminTours'),last=localStorage.getItem('phoenixLastBackup');$id('backupBookingsCount').textContent=`${bookings.length} booking${bookings.length===1?'':'s'}`;$id('backupToursCount').textContent=`${tours.length} tour${tours.length===1?'':'s'}`;$id('backupLastTime').textContent=last?`Last backup: ${new Date(last).toLocaleString()}`:'No backup created yet'}function status(message,type='ok'){const el=$id('backupStatus');el.textContent=message;el.className=`backup-status show ${type}`;clearTimeout(status.timer);status.timer=setTimeout(()=>{el.className='backup-status'},5000)}function filename(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return`phoenix-tours-backup-${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}.json`}function createBackup(){try{const now=new Date().toISOString();localStorage.setItem('phoenixLastBackup',now);const storage={};for(const key of STORAGE_KEYS){const value=localStorage.getItem(key);if(value!==null)storage[key]=value}const backup={format:'phoenix-tours-backup',version:1,createdAt:now,app:'Phoenix Tours Admin',storage};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename();document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);updateMeta();status('Backup created successfully. Keep the downloaded JSON file somewhere safe.')}catch(error){console.error(error);status('Could not create the backup. Please try again.','err')}}async function restoreFile(file){try{const text=await file.text();const backup=JSON.parse(text);if(!backup||backup.format!=='phoenix-tours-backup'||!backup.storage||typeof backup.storage!=='object')throw new Error('Invalid backup format');const allowed=STORAGE_KEYS.filter(key=>Object.prototype.hasOwnProperty.call(backup.storage,key));if(!allowed.length)throw new Error('No Phoenix Tours data found');let bookingCount=0,tourCount=0;try{bookingCount=JSON.parse(backup.storage.phoenixBookings||'[]').length||0}catch{}try{tourCount=JSON.parse(backup.storage.phoenixAdminTours||'[]').length||0}catch{}const created=backup.createdAt?new Date(backup.createdAt).toLocaleString():'unknown date';const ok=confirm(`Restore Phoenix Tours backup?\n\nBackup date: ${created}\nBookings: ${bookingCount}\nTours: ${tourCount}\n\nThis will replace the current dashboard data in this browser.`);if(!ok)return;for(const key of STORAGE_KEYS){if(Object.prototype.hasOwnProperty.call(backup.storage,key)){const value=backup.storage[key];if(typeof value!=='string')throw new Error(`Invalid value for ${key}`);JSON.parse(value);localStorage.setItem(key,value)}}localStorage.setItem('phoenixLastRestore',new Date().toISOString());status('Backup restored successfully. Reloading dashboard…');setTimeout(()=>location.reload(),700)}catch(error){console.error(error);status('This file is not a valid Phoenix Tours backup. Nothing was changed.','err')}}$id('createBackupBtn').addEventListener('click',createBackup);$id('restoreBackupBtn').addEventListener('click',()=>$id('restoreBackupFile').click());$id('restoreBackupFile').addEventListener('change',event=>{const file=event.target.files?.[0];if(file)restoreFile(file);event.target.value=''});updateMeta()})();